### Expected behavior

`"use client"` should be either 1 line above or below `"use strict"`. I believe either is acceptable for Next.js.


```
// output.js
"use client";
"use strict";
Object.defineProperty(exports, "__esModule", {
    value: true
});
Object.defineProperty(exports, "ReactClientComponent", {
    enumerable: true,
    get: function() {
        return ReactClientComponent;
    }
});
function ReactClientComponent() {
    return "Hello world";
}
```

